OPOSICIONES.push({"id": "barakaldo-conserje-escolar", "nombre": "Conserje Escolar · Ayuntamiento de Barakaldo", "sub": "9 plazas, grupo AP. Bases: BOB nº 134, 16/07/2026. 1.º ejercicio: 60 preguntas + 10 de reserva, 90 min. 2.º: 30 supuestos tipo test + 10 de reserva, 60 min. 4 opciones, cada fallo resta 1/3; se aprueba con 15 sobre 30. Fecha sin publicar.", "sim": {"n": 60, "min": 90, "pena": "0.3333333333"}, "temas": [{"id": "t01", "sig": "Tema 1", "titulo": "Tema 1. La Constitución Española. Título Preliminar. Derechos y deberes fundamentales (artículos 14 a 29)", "sub": "Parte general. Solo preguntas de los arts. 1 a 9 y 14 a 29, sacadas de tus otros tests.", "preguntas": [], "incluye": ["biblioteca-dfb/t01:1-10+15-24+33", "ehu-administrativa/b01:1-8", "ehu-administrativa/b05:11", "ehu-administrativa/b08:58", "getxo-conserje/t09:29", "getxo-conserje/ex27:1+3-4+38", "getxo-conserje/ex27c:4-5", "getxo-kirolak-auxiliar/t01:4-24", "getxo-kirolak-auxiliar/t02:16", "gobierno-vasco-administrativo/x17:40"]}, {"id": "t02", "sig": "Tema 2", "titulo": "Tema 2. Estatuto de Autonomía del País Vasco. Título Preliminar. Competencias exclusivas (art. 10). Título II: poderes del País Vasco (arts. 24 a 39)", "sub": "Parte general. Solo preguntas de los arts. 1 a 10 y 24 a 39.", "preguntas": [], "incluye": ["abanto-administrativo/t09:1-9", "biblioteca-dfb/t02:2-10+16-27", "biblioteca-dfb/ex18:8", "biblioteca-dfb/mx:2", "ehu-administrativa/b01:12-14+16+18", "getxo-administrativo/t03:1-10+20", "getxo-administrativo/t04:23", "getxo-conserje/ex27:6-8", "getxo-conserje/ex27c:11-15", "getxo-kirolak-auxiliar/t03:2+6-7", "gobierno-vasco-administrativo/t04:3+5-6+10-11+13+18", "gobierno-vasco-administrativo/x17:3"]}, {"id": "t03", "sig": "Tema 3", "titulo": "Tema 3. La organización municipal: art. 140 CE. LBRL arts. 19 y 20. Ley 2/2016 de Instituciones Locales de Euskadi: deberes y derechos de las personas vecinas (arts. 43 a 46)", "sub": "Parte general. Solo preguntas de esos artículos.", "preguntas": [{"id": "bkt03q11", "q": "Según el artículo 19.1 de la Ley 7/1985 (LBRL), el gobierno y la administración municipal corresponde al ayuntamiento, salvo:", "o": ["En los municipios que legalmente funcionen en régimen de Concejo Abierto", "En los municipios de gran población", "En los municipios de menos de 5.000 habitantes", "En las capitales de provincia"], "e": "El art. 19.1 exceptúa los municipios en régimen de Concejo Abierto.", "r": "LBRL art. 19.1"}, {"id": "bkt03q12", "q": "Según el artículo 19.1 de la LBRL, el ayuntamiento está integrado por:", "o": ["El Alcalde y los Concejales", "El Alcalde y la Junta de Gobierno Local", "El Pleno y las comisiones informativas", "Los Tenientes de Alcalde y el Secretario"], "e": "Art. 19.1: el ayuntamiento está integrado por el Alcalde y los Concejales.", "r": "LBRL art. 19.1"}, {"id": "bkt03q13", "q": "Según el artículo 19.2 de la LBRL, el Alcalde es elegido:", "o": ["Por los Concejales o por los vecinos, en los términos de la legislación electoral general", "Siempre directamente por los vecinos", "Por el Pleno a propuesta de la Junta de Gobierno", "Por la Diputación Foral"], "e": "Art. 19.2: los Concejales se eligen por sufragio universal, igual, libre, directo y secreto; el Alcalde, por los Concejales o por los vecinos.", "r": "LBRL art. 19.2"}, {"id": "bkt03q14", "q": "Según el artículo 19.3 de la LBRL, el régimen de organización de los municipios de gran población se ajusta a lo dispuesto en:", "o": ["El título X de la propia LBRL", "El reglamento orgánico de cada municipio exclusivamente", "La Ley 2/2016 de Instituciones Locales de Euskadi", "La Constitución"], "e": "Art. 19.3: los municipios del título X se rigen por él y, en lo no previsto, por el régimen común.", "r": "LBRL art. 19.3"}], "incluye": ["getxo-administrativo/t02:3-4", "getxo-kirolak-auxiliar/t02:7+22+40", "abanto-administrativo/t32:18", "abanto-administrativo/t33:4", "abanto-administrativo/t34:6", "getxo-administrativo/t25:10-11", "abanto-administrativo/t31:1-7+9-10", "getxo-conserje/t03:1-4", "getxo-conserje/ex27:12-13"]}, {"id": "t04", "sig": "Tema 4", "titulo": "Tema 4. Ley 39/2015: derechos de las personas (art. 13). Ley 40/2015: principios generales (arts. 3 y 4)", "sub": "Parte general. Solo preguntas de esos artículos.", "preguntas": [], "incluye": ["biblioteca-dfb/t06:3", "ehu-administrativa/b08:40+43+60+72", "getxo-kirolak-auxiliar/t19:1-4+14-15", "abanto-administrativo/t11:2+8-9", "getxo-administrativo/t17:3-6", "gobierno-vasco-administrativo/x17:11"]}, {"id": "t05", "sig": "Tema 5", "titulo": "Tema 5. DL 1/2023 de igualdad: Título Preliminar (arts. 1 a 3) y Administración Local (art. 7). II Plan de igualdad interno del Ayuntamiento de Barakaldo: ejes y objetivos", "sub": "Parte general. DL 1/2023 arts. 1 a 3 y 7, y ejes y objetivos del II Plan de igualdad interno de Barakaldo (2022-2026).", "preguntas": [{"id": "bkt05q11", "q": "¿Qué artículo del Decreto Legislativo 1/2023 regula las funciones de la Administración local en materia de igualdad?", "o": ["El artículo 7", "El artículo 3", "El artículo 1", "El artículo 12"], "e": "El art. 7 se titula «De la Administración local».", "r": "DL 1/2023 art. 7"}, {"id": "bkt05q12", "q": "Según el art. 7.1 del DL 1/2023, los ayuntamientos ejercen sus funciones de igualdad individualmente o a través de:", "o": ["Mancomunidades, cuadrillas o agrupaciones", "Las diputaciones forales exclusivamente", "Emakunde", "Las juntas generales"], "e": "Art. 7.1: individualmente o a través de mancomunidades, cuadrillas o agrupaciones.", "r": "DL 1/2023 art. 7.1"}, {"id": "bkt05q13", "q": "¿Cuál de estas NO es una función de los ayuntamientos según el art. 7.1 del DL 1/2023?", "o": ["Aprobar el plan general para la igualdad de mujeres y hombres de toda la Comunidad Autónoma", "Ejecutar medidas de acción positiva en el ámbito local", "Mantener estadísticas actualizadas sobre la situación diferencial de mujeres y hombres", "Realizar actividades de sensibilización sobre la desigualdad"], "e": "El plan general de la CAE corresponde al Gobierno Vasco. Las otras tres figuran en el art. 7.1 (letras b, d y f).", "r": "DL 1/2023 art. 7.1"}, {"id": "bkt05q14", "q": "Según el art. 7.1.c del DL 1/2023, la planificación municipal en igualdad se hace en el marco de:", "o": ["La planificación general del Gobierno Vasco y de las diputaciones forales", "La planificación del Estado", "Los planes de la Unión Europea exclusivamente", "Ningún marco: cada ayuntamiento decide libremente"], "e": "Art. 7.1.c: planificación local en el marco de la planificación general del Gobierno y de las diputaciones forales.", "r": "DL 1/2023 art. 7.1.c"}, {"id": "bkt05q15", "q": "El art. 7.1.i del DL 1/2023 cita las escuelas de empoderamiento y las casas de mujeres como ejemplos de:", "o": ["Programas, servicios o recursos para el empoderamiento de las mujeres", "Órganos de gobierno municipal", "Centros educativos públicos", "Servicios de atención a la infancia"], "e": "La letra i) se refiere a programas, servicios o recursos para el empoderamiento de las mujeres.", "r": "DL 1/2023 art. 7.1.i"}, {"id": "bkt05q16", "q": "Según el art. 7.2 del DL 1/2023, para ejercer estas funciones las administraciones locales cuentan con la asistencia de:", "o": ["La Administración autonómica y las forales, especialmente las de menor capacidad económica y de gestión", "El Ministerio de Igualdad", "Las empresas privadas del municipio", "Ninguna otra administración"], "e": "Art. 7.2: asistencia técnica de la Administración autonómica y de las forales, en especial a las de menor capacidad.", "r": "DL 1/2023 art. 7.2"}, {"id": "bkt05q17", "q": "Según el art. 7.1 del DL 1/2023, ¿qué función municipal consiste en ofrecer recursos para que la vida personal, laboral y familiar sea compatible?", "o": ["Establecer recursos para la conciliación corresponsable", "Detectar situaciones de discriminación", "Realizar estudios e investigaciones", "Hacer seguimiento de la normativa local"], "e": "Es la letra j) del art. 7.1.", "r": "DL 1/2023 art. 7.1.j"}, {"id": "bkt05p01", "q": "¿Cuántos ejes tiene el II Plan de Igualdad Interno del Ayuntamiento de Barakaldo?", "o": ["Cuatro", "Tres", "Cinco", "Seis"], "e": "Ejes I a IV.", "r": "II Plan Igualdad interno Barakaldo, estructura"}, {"id": "bkt05p02", "q": "¿Cómo se llama el Eje I del II Plan de Igualdad Interno de Barakaldo?", "o": ["Cultura organizacional y compromiso con la igualdad", "Condiciones laborales y gestión de personas", "Salud y seguridad laboral", "Ejercicio corresponsable de los derechos de la vida personal, familiar y laboral"], "e": "Eje I: Cultura organizacional y compromiso con la igualdad.", "r": "II Plan Igualdad interno Barakaldo, Eje I"}, {"id": "bkt05p03", "q": "¿Cómo se llama el Eje II del II Plan de Igualdad Interno de Barakaldo?", "o": ["Condiciones laborales y gestión de personas", "Cultura organizacional y compromiso con la igualdad", "Salud y seguridad laboral", "Comunicación y participación"], "e": "Eje II: Condiciones laborales y gestión de personas.", "r": "II Plan Igualdad interno Barakaldo, Eje II"}, {"id": "bkt05p04", "q": "¿Cómo se llama el Eje III del II Plan de Igualdad Interno de Barakaldo?", "o": ["Ejercicio corresponsable de los derechos de la vida personal, familiar y laboral", "Salud y seguridad laboral", "Condiciones laborales y gestión de personas", "Vidas libres de violencia machista"], "e": "Eje III: Ejercicio corresponsable de los derechos de la vida personal, familiar y laboral.", "r": "II Plan Igualdad interno Barakaldo, Eje III"}, {"id": "bkt05p05", "q": "¿Cómo se llama el Eje IV del II Plan de Igualdad Interno de Barakaldo?", "o": ["Salud y seguridad laboral", "Cultura organizacional y compromiso con la igualdad", "Empoderamiento de las mujeres", "Condiciones laborales y gestión de personas"], "e": "Eje IV: Salud y seguridad laboral.", "r": "II Plan Igualdad interno Barakaldo, Eje IV"}, {"id": "bkt05p06", "q": "¿En qué eje del II Plan de Igualdad Interno está el objetivo «Garantizar el principio de igualdad retributiva entre la plantilla del Ayuntamiento»?", "o": ["Eje II. Condiciones laborales y gestión de personas", "Eje I. Cultura organizacional y compromiso con la igualdad", "Eje III. Ejercicio corresponsable", "Eje IV. Salud y seguridad laboral"], "e": "Es el objetivo 2.3.", "r": "II Plan Igualdad interno Barakaldo, objetivo 2.3"}, {"id": "bkt05p07", "q": "¿En qué eje está el objetivo «Asegurar un espacio laboral libre de situaciones de acoso sexual y/o por razón de sexo»?", "o": ["Eje IV. Salud y seguridad laboral", "Eje II. Condiciones laborales y gestión de personas", "Eje I. Cultura organizacional y compromiso con la igualdad", "Eje III. Ejercicio corresponsable"], "e": "Es el objetivo 4.1.", "r": "II Plan Igualdad interno Barakaldo, objetivo 4.1"}, {"id": "bkt05p08", "q": "El objetivo «Aplicar un uso del lenguaje e imágenes inclusivas en todas las comunicaciones, internas y externas» pertenece al:", "o": ["Eje I (objetivo 1.3)", "Eje II (objetivo 2.2)", "Eje III (objetivo 3.1)", "Eje IV (objetivo 4.2)"], "e": "Objetivo 1.3 del Eje I.", "r": "II Plan Igualdad interno Barakaldo, objetivo 1.3"}, {"id": "bkt05p09", "q": "El objetivo 3.2 del II Plan de Igualdad Interno busca mejorar las medidas de conciliación corresponsable e impulsar estrategias para aumentar su utilización entre:", "o": ["Los hombres", "Las mujeres", "El personal temporal", "Los cargos directivos"], "e": "Objetivo 3.2: aumentar su utilización entre los hombres.", "r": "II Plan Igualdad interno Barakaldo, objetivo 3.2"}, {"id": "bkt05p10", "q": "¿Qué objetivo del Eje II se refiere a reducir la segregación horizontal y vertical?", "o": ["Fortalecer los procesos de selección/contratación y de promoción (objetivo 2.1)", "Garantizar la igualdad retributiva (objetivo 2.3)", "Eliminar desigualdades en el empleo temporal (objetivo 2.4)", "Impulsar la formación en igualdad (objetivo 1.2)"], "e": "Objetivo 2.1: selección/contratación para reducir la segregación horizontal y promoción para reducir la vertical.", "r": "II Plan Igualdad interno Barakaldo, objetivo 2.1"}, {"id": "bkt05p11", "q": "El objetivo 2.2 del II Plan de Igualdad Interno pretende fomentar la presencia de las mujeres:", "o": ["En los puestos en los que están infrarrepresentadas", "En los cargos políticos", "En el empleo temporal", "En las comisiones de igualdad"], "e": "Objetivo 2.2: presencia de mujeres en puestos donde están infrarrepresentadas.", "r": "II Plan Igualdad interno Barakaldo, objetivo 2.2"}, {"id": "bkt05p12", "q": "El objetivo 2.4 del II Plan de Igualdad Interno se centra en eliminar desigualdades entre mujeres y hombres en:", "o": ["El empleo temporal de las mujeres", "La formación", "La salud laboral", "La comunicación externa"], "e": "Objetivo 2.4: empleo temporal de las mujeres.", "r": "II Plan Igualdad interno Barakaldo, objetivo 2.4"}, {"id": "bkt05p13", "q": "¿Qué objetivo del Eje IV se refiere a las mujeres víctimas de violencia machista?", "o": ["Garantizar los derechos y recursos existentes para mujeres víctimas de violencia machista (4.3)", "Incorporar la perspectiva de género en la salud laboral (4.2)", "Asegurar un espacio libre de acoso (4.1)", "Comunicar las medidas de conciliación (3.1)"], "e": "Objetivo 4.3.", "r": "II Plan Igualdad interno Barakaldo, objetivo 4.3"}, {"id": "bkt05p14", "q": "El objetivo 4.2 del II Plan de Igualdad Interno consiste en:", "o": ["Incorporar la perspectiva de género en la salud y seguridad laboral de la plantilla", "Revisar el lenguaje de las comunicaciones", "Hacer la valoración de puestos de trabajo", "Difundir el catálogo de medidas de conciliación"], "e": "Objetivo 4.2.", "r": "II Plan Igualdad interno Barakaldo, objetivo 4.2"}, {"id": "bkt05p15", "q": "¿Qué objetivo del Eje I se refiere a la formación?", "o": ["Impulsar la formación en igualdad de las personas trabajadoras para reforzar el compromiso con la igualdad (1.2)", "Establecer canales de comunicación y participación (1.4)", "Garantizar la igualdad de trato en la cultura organizacional (1.1)", "Fortalecer los procesos de selección (2.1)"], "e": "Objetivo 1.2.", "r": "II Plan Igualdad interno Barakaldo, objetivo 1.2"}, {"id": "bkt05p16", "q": "El objetivo 1.4 del II Plan de Igualdad Interno es:", "o": ["Establecer y reforzar los canales de comunicación y participación (internas y externas)", "Aplicar un lenguaje inclusivo", "Garantizar la igualdad retributiva", "Asegurar un espacio libre de acoso"], "e": "Objetivo 1.4.", "r": "II Plan Igualdad interno Barakaldo, objetivo 1.4"}, {"id": "bkt05p17", "q": "El objetivo 3.1 del II Plan de Igualdad Interno consiste en:", "o": ["Comunicar, difundir y hacer seguimiento de la utilización de las medidas de conciliación de la plantilla", "Aumentar el uso de la conciliación entre los hombres", "Revisar el protocolo de acoso", "Reducir la segregación vertical"], "e": "Objetivo 3.1.", "r": "II Plan Igualdad interno Barakaldo, objetivo 3.1"}, {"id": "bkt05p18", "q": "¿Qué eje del II Plan de Igualdad Interno tiene solo dos objetivos?", "o": ["Eje III", "Eje I", "Eje II", "Eje IV"], "e": "Eje I y II: 4 objetivos cada uno; Eje III: 2; Eje IV: 3.", "r": "II Plan Igualdad interno Barakaldo, estructura"}, {"id": "bkt05p19", "q": "¿A quién se dirigen los objetivos y medidas del II Plan de Igualdad Interno del Ayuntamiento de Barakaldo?", "o": ["A la plantilla municipal del Ayuntamiento", "A toda la ciudadanía de Barakaldo", "A las empresas del municipio", "Al alumnado de los centros escolares"], "e": "Ámbito de aplicación: la plantilla municipal.", "r": "II Plan Igualdad interno Barakaldo, ámbito"}, {"id": "bkt05p20", "q": "¿Qué vigencia tiene el II Plan de Igualdad Interno del Ayuntamiento de Barakaldo?", "o": ["4 años desde su aprobación por la Comisión Negociadora", "2 años", "6 años", "Indefinida"], "e": "Vigencia de 4 años desde la aprobación por la Comisión Negociadora (2022-2026).", "r": "II Plan Igualdad interno Barakaldo, vigencia"}], "incluye": ["biblioteca-dfb/t09:4-12", "getxo-administrativo/t08:19", "getxo-conserje/ex27:14-17", "getxo-conserje/ex27c:40", "getxo-kirolak-auxiliar/t05:35-44+46-48"]}, {"id": "t06", "sig": "Tema 6", "titulo": "Tema 6. Ley 10/1982 del euskera (arts. 1 a 14). Plan Estratégico de Normalización del Uso del Euskera, VII periodo (2023-2027): ejes (págs. 5 a 11)", "sub": "Parte general. Ley 10/1982 (arts. 1 a 14) y marco KEMEN del VII periodo de planificación (directrices del Gobierno Vasco). OJO: las bases citan otro documento («Plan Estratégico… págs. 5 a 11»).", "preguntas": [{"id": "bkt06q01", "q": "El VII periodo de planificación (VII Plan de normalización del uso del euskera) que entra en este temario abarca los años:", "o": ["2023-2027", "2018-2022", "2020-2024", "2026-2030"], "e": "Las bases citan el VII Plan de normalización del uso del euskera 2023-2027.", "r": "BOB nº 134, 16/07/2026, Anexo I"}, {"id": "bkk01", "q": "¿Cómo se llama el marco de gestión y uso para la normalización del euskera del VII periodo de planificación?", "o": ["KEMEN", "EME", "Bikain", "AriGara"], "e": "KEMEN es el nuevo marco; EME era el marco estándar de 2017, Bikain es un certificado y AriGara una plataforma.", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk02", "q": "¿En cuántos ejes se estructura el marco KEMEN?", "o": ["Dos: Gestión y Uso", "Tres: Gestión, Uso e Imagen", "Cuatro", "Trece"], "e": "KEMEN está estructurado en 2 ejes y contempla 13 áreas.", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk03", "q": "¿Cuántas áreas contempla el marco KEMEN?", "o": ["13", "2", "48", "14"], "e": "2 ejes y 13 áreas. El sistema de indicadores tiene 48 indicadores y 14 comunes (panel de control).", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk04", "q": "¿Cuál de estas áreas pertenece al eje GESTIÓN de KEMEN?", "o": ["Liderazgo", "Imagen", "Relaciones externas", "Recursos informáticos"], "e": "Gestión: gestión general del euskera, personal, comunicación de la estrategia, liderazgo, competencia lingüística y cláusulas lingüísticas.", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk05", "q": "¿Cuál de estas áreas pertenece al eje USO de KEMEN?", "o": ["Comunicaciones con la ciudadanía", "Competencia lingüística", "Cláusulas lingüísticas", "Personal"], "e": "Uso: imagen, relaciones internas, formación, lengua de creación, comunicaciones con la ciudadanía, relaciones externas y recursos informáticos.", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk06", "q": "En el marco KEMEN, el área «Formación» se encuadra en el eje:", "o": ["Uso", "Gestión", "Liderazgo", "No pertenece a ningún eje"], "e": "En el esquema de KEMEN, Formación aparece en el eje Uso.", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk07", "q": "¿Cuántos indicadores tiene el sistema de indicadores del VII periodo de planificación?", "o": ["48 (en 2 ejes y 13 áreas)", "14", "13", "100"], "e": "2 ejes, 13 áreas y 48 indicadores; 14 son comunes a todas las organizaciones (panel de control).", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk08", "q": "¿Qué es el «panel de control» del sistema de indicadores del VII periodo?", "o": ["14 indicadores comunes que medirán todas las entidades del sector público de la CAE", "El cuadro eléctrico de cada edificio", "Un certificado de calidad", "El órgano que aprueba los planes"], "e": "Es la batería mínima de 14 indicadores comunes.", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk09", "q": "¿Qué es Bikain?", "o": ["Un certificado oficial y gratuito que acredita el grado de normalización del euskera en una organización", "Una plataforma web para personal técnico de euskera", "El traductor neuronal del Gobierno Vasco", "El servicio de garantía de los derechos lingüísticos"], "e": "Bikain es el Certificado de Calidad en la Gestión Lingüística; tiene tres niveles: básico, medio y superior.", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk10", "q": "¿Qué es AriGara?", "o": ["Una plataforma de Internet para el personal técnico de normalización del euskera", "Un certificado de calidad", "Un marco de gestión", "Un decreto de normalización"], "e": "AriGara es un portal creado en 2021 como punto de encuentro del personal a cargo de la normalización.", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}, {"id": "bkk11", "q": "¿Cuál es el principal objetivo de KEMEN, además de obtener datos más fiables?", "o": ["Integrar la gestión lingüística en la gestión general de la institución", "Sustituir la Ley 10/1982", "Eliminar los perfiles lingüísticos", "Traducir automáticamente todos los documentos"], "e": "Según las directrices, el principal objetivo es integrar la gestión lingüística en la gestión general.", "r": "Directrices VII periodo de planificación (Gobierno Vasco, 2023), KEMEN"}], "incluye": ["biblioteca-dfb/t08:3-6+9-14+16-18", "biblioteca-dfb/mx:3", "ehu-administrativa/b05:58", "ehu-administrativa/b06:1-4", "getxo-conserje/ex27:9", "getxo-conserje/ex27c:16-20", "getxo-kirolak-auxiliar/t04:1-14+17-21", "getxo-kirolak-auxiliar/t13:15", "gobierno-vasco-administrativo/t08:11"]}, {"id": "t07", "sig": "Tema 7", "titulo": "Tema 7. Comunicación y atención a la ciudadanía: comunicación oral, atención presencial, comunicación telefónica, atención intercultural y aspectos básicos de protección de datos (introducción y conceptos)", "sub": "Parte específica Incluye preguntas hechas con el temario del IVAP de Personal de Apoyo.", "preguntas": [{"id": "bkt07q11", "q": "Según el RGPD (art. 4.1), un «dato personal» es:", "o": ["Toda información sobre una persona física identificada o identificable", "Solo el nombre, apellidos y DNI de una persona", "Cualquier información de una empresa", "Solo los datos de salud"], "e": "Art. 4.1 RGPD: toda información sobre una persona física identificada o identificable (el «interesado»).", "r": "RGPD art. 4.1"}, {"id": "bkt07q12", "q": "Según el RGPD (art. 4.2), el «tratamiento» de datos personales incluye:", "o": ["Cualquier operación sobre datos: recoger, registrar, conservar, consultar, comunicar o destruir, entre otras", "Solo su publicación en internet", "Solo su venta a terceros", "Solo su almacenamiento informático"], "e": "El tratamiento abarca cualquier operación, automatizada o no, sobre datos personales.", "r": "RGPD art. 4.2"}, {"id": "bkt07q13", "q": "Según el RGPD (art. 4.8), el «encargado del tratamiento» es quien:", "o": ["Trata datos personales por cuenta del responsable del tratamiento", "Decide los fines y medios del tratamiento", "Es la persona cuyos datos se tratan", "Controla a todas las administraciones en materia de datos"], "e": "El encargado trata datos por cuenta del responsable; el responsable decide fines y medios.", "r": "RGPD art. 4.8"}, {"id": "bki01", "q": "Según el temario del IVAP, la diversidad intercultural supone que las diferencias culturales se dan:", "o": ["En los dos sentidos: de quien presta el servicio hacia quien lo recibe y a la inversa", "Solo de la persona usuaria hacia la Administración", "Solo cuando la persona no habla el idioma", "Solo en los servicios sociales"], "e": "Ambas partes perciben a la otra como diferente.", "r": "Temario IVAP Personal de Apoyo (2021), tema 17, atención intercultural"}, {"id": "bki02", "q": "En las culturas «emocionales», según el temario del IVAP:", "o": ["La expresión de emociones es más expansiva y puede haber enfados o voz elevada", "Las emociones se consideran un estorbo para razonar", "No se expresan las emociones en público", "La puntualidad es más importante que en otras"], "e": "En las culturas neutras, en cambio, se considera que las emociones enturbian el razonamiento.", "r": "Temario IVAP Personal de Apoyo (2021), tema 17, atención intercultural"}, {"id": "bki03", "q": "Al atender a una persona de una cultura «neutra», quien presta el servicio debe:", "o": ["Mantener un tono positivo y constante y completar la información que pueda necesitar, porque suele dar poco feedback", "Elevar la voz para provocar una reacción", "Dar por hecho que lo ha entendido todo", "Acortar la atención"], "e": "En las culturas neutras suele faltar información sobre si se está comprendiendo.", "r": "Temario IVAP Personal de Apoyo (2021), tema 17, atención intercultural"}, {"id": "bki04", "q": "¿Cuál de estos NO es uno de los principios de la atención intercultural en la Administración según el temario del IVAP?", "o": ["Uniformidad: tratar igual a todas las culturas sin tener en cuenta sus diferencias", "Respeto y reconocimiento de la otra parte", "Comprensión de las singularidades y necesidades", "Favorecimiento de la autonomía de las personas"], "e": "Los principios son respeto y reconocimiento, comprensión, actitud favorable a la interlocución y favorecer la autonomía.", "r": "Temario IVAP Personal de Apoyo (2021), tema 17, atención intercultural"}, {"id": "bki05", "q": "Según el temario del IVAP, la atención intercultural debe ofrecer a las personas usuarias un trato:", "o": ["Inclusivo, comprensivo e integrador", "Neutro y distante", "Diferente según su país de origen", "Exclusivamente por escrito"], "e": "Su elemento esencial es una actitud positiva hacia las personas de otras culturas.", "r": "Temario IVAP Personal de Apoyo (2021), tema 17, atención intercultural"}, {"id": "bki06", "q": "¿Qué otros dos elementos de diversidad cultural destaca el temario del IVAP, además de la expresión de emociones?", "o": ["La percepción del tiempo y la percepción del poder", "La religión y la gastronomía", "El idioma y la vestimenta", "La edad y el sexo"], "e": "El rigor con el tiempo y la consideración de la Administración como poder varían según la cultura.", "r": "Temario IVAP Personal de Apoyo (2021), tema 17, atención intercultural"}, {"id": "bki07", "q": "Según el temario del IVAP, ¿qué característica tiene la comunicación oral?", "o": ["Es efímera: termina cuando dejan de oírse las palabras", "Deja constancia permanente", "Es siempre unidireccional", "No admite improvisación"], "e": "También es bidireccional, en tiempo real y tiende a la improvisación.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki08", "q": "Las tres áreas de estudio de la comunicación no verbal son:", "o": ["Kinésica, proxémica y paralingüística", "Fonética, sintaxis y semántica", "Escucha, empatía y asertividad", "Presentación, respuesta y cierre"], "e": "Kinésica (gestos, mirada, postura), proxémica (distancias) y paralingüística (voz).", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki09", "q": "La proxémica estudia:", "o": ["El espacio y la distancia que guardan las personas al comunicarse", "Los gestos de la cara", "El tono y el volumen de la voz", "Las palabras técnicas"], "e": "E. T. Hall definió cuatro distancias: íntima, personal, social y pública.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki10", "q": "Según E. T. Hall, la distancia «personal» (oficina, reuniones, conversaciones de trabajo) va de:", "o": ["45 a 120 cm", "14 a 45 cm", "120 a 360 cm", "Más de 360 cm"], "e": "Íntima 14-45 cm, personal 45-120 cm, social 120-360 cm y pública más de 360 cm.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki11", "q": "En la comunicación no verbal, la mirada «laboral o profesional» se caracteriza porque:", "o": ["No cae por debajo del nivel de los ojos del interlocutor", "Cae por debajo de los ojos", "Recorre el cuerpo de arriba abajo", "Evita mirar a la persona"], "e": "La mirada social cae por debajo de los ojos y la íntima recorre el cuerpo.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki12", "q": "Según el temario del IVAP, para que un mensaje oral sea entendible el ritmo debe ser de:", "o": ["Entre 100 y 150 palabras por minuto", "Entre 50 y 80 palabras por minuto", "Más de 200 palabras por minuto", "Entre 20 y 40 palabras por minuto"], "e": "El ritmo es el número de palabras por minuto.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki13", "q": "¿Cuáles son las cuatro fases de la atención presencial según el temario del IVAP?", "o": ["Contacto inicial o acogida, identificación de la necesidad, gestión de la necesidad y cierre", "Saludo, queja, respuesta y despedida", "Presentación, escucha, respuesta y despedida", "Recepción, registro, tramitación y archivo"], "e": "En la atención telefónica las fases son presentación, escucha e identificación, respuesta y despedida.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki14", "q": "En la fase de gestión de la necesidad, los tres niveles de gestión son:", "o": ["Orientación, tramitación y derivación", "Información, registro y archivo", "Escucha, empatía y asertividad", "Acogida, espera y cierre"], "e": "Si no se puede resolver, se orienta o se deriva; nunca se responde «No lo sé».", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki15", "q": "Si una persona debe ser atendida por otro compañero, lo correcto según el temario del IVAP es:", "o": ["Acompañarla, presentársela y explicarle el asunto para que no tenga que repetirlo", "Indicarle el despacho y que vaya sola", "Pedirle que vuelva otro día", "Darle el teléfono del compañero"], "e": "Si no se puede acompañar, al menos se pone en antecedentes al compañero por teléfono.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki16", "q": "¿Qué fórmula de trato se usa en un primer momento con cualquier persona usuaria?", "o": ["Usted", "Tú", "Depende de su edad", "El nombre de pila"], "e": "Solo con jóvenes y según las circunstancias puede usarse el «tú».", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki17", "q": "Según el temario del IVAP, ¿antes de qué tono conviene contestar el teléfono?", "o": ["Antes del tercer tono", "Antes del sexto tono", "Al primer tono siempre", "No importa"], "e": "Lo recomendable es contestar antes del tercer tono.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki18", "q": "¿Cuánto tiempo como máximo se debe mantener en espera a quien llama?", "o": ["30 segundos", "2 minutos", "5 minutos", "10 segundos"], "e": "No hay que mantener al interlocutor en espera mucho tiempo: como máximo, 30 segundos.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki19", "q": "La «sonrisa telefónica» consiste en:", "o": ["Que el tono de la conversación refleje amabilidad y simpatía", "Sonreír al descolgar aunque no se hable", "Hacer bromas para relajar", "Hablar más rápido"], "e": "En la comunicación telefónica la voz es el único canal.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki20", "q": "Si llaman preguntando por una persona que no está, lo correcto es:", "o": ["Decir «No está en estos momentos», ofrecer ayuda y tomar nota si hace falta, sin explicar por qué no está", "Explicar dónde ha ido y cuándo vuelve", "Dar su móvil personal", "Colgar y no anotar nada"], "e": "No se dan explicaciones de por qué no está ni del tiempo que lleva fuera.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki21", "q": "Al tomar un aviso telefónico para otra persona hay que anotar:", "o": ["Fecha y hora, nombre y cargo o entidad de quien llama, modo de contacto y mensaje resumido", "Solo el nombre de quien llama", "Solo el mensaje", "El DNI de quien llama"], "e": "Se recogen en impresos habilitados para ello.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki22", "q": "En la atención telefónica, si la respuesta exige un trámite o consulta interna, la respuesta será de tipo:", "o": ["Anotación y llamada posterior", "Inmediata", "Derivada", "Ninguna: se cuelga"], "e": "Las respuestas pueden ser inmediatas, de anotación y llamada posterior o derivadas.", "r": "Temario IVAP Personal de Apoyo (2021), tema 19"}, {"id": "bki23", "q": "Según el temario del IVAP, el derecho a la protección de datos personales está reconocido en la Constitución en el artículo:", "o": ["18.4", "27", "14", "24"], "e": "El art. 18.4 CE dice que la ley limitará el uso de la informática para garantizar el honor y la intimidad.", "r": "Temario IVAP Personal de Apoyo (2021), tema 10 · RGPD art. 4"}, {"id": "bki24", "q": "¿Cuál es un ejemplo de dato personal «identificable» según el temario del IVAP?", "o": ["La matrícula de un vehículo, porque a través del Registro de Vehículos se puede saber quién es el titular", "El nombre de una empresa", "Una cifra estadística anónima", "El tiempo que hace hoy"], "e": "Identificable es lo que no se conoce directamente pero es razonablemente fácil conocer.", "r": "Temario IVAP Personal de Apoyo (2021), tema 10 · RGPD art. 4"}, {"id": "bki25", "q": "Una empresa informática contratada para el mantenimiento de los ordenadores municipales, que accede a datos personales, es:", "o": ["Encargada del tratamiento", "Responsable del tratamiento", "Interesada", "Delegada de protección de datos"], "e": "Trata datos por cuenta del responsable, con las condiciones que este fija por escrito.", "r": "Temario IVAP Personal de Apoyo (2021), tema 10 · RGPD art. 4"}, {"id": "bki26", "q": "¿Se aplica el derecho a la protección de datos a las personas fallecidas, según el temario del IVAP?", "o": ["No: es un derecho de las personas físicas vivas", "Sí, igual que a las vivas", "Solo durante cinco años", "Solo si lo piden sus herederos"], "e": "El temario dice que es un derecho de las personas físicas y no se aplica a las fallecidas.", "r": "Temario IVAP Personal de Apoyo (2021), tema 10 · RGPD art. 4"}], "incluye": ["getxo-kirolak-auxiliar/t14:1-17", "getxo-conserje/t08:3-5+7-10", "ehu-administrativa/b07:18+25-28+31+34-35", "ehu-administrativa/b08:48-51+53+59+66+73", "ehu-administrativa/b09:2+4-9+11-12", "ehu-administrativa/b10:5-38", "getxo-conserje/ex27:64-67+69-73", "getxo-conserje/ex27c:62-65+67-68+71-72"]}, {"id": "t08", "sig": "Tema 8", "titulo": "Tema 8. Ley 31/1995 de PRL: derechos y obligaciones. Posturas corporales y prevención de lesiones al mover equipos y materiales: técnicas de manipulación de cargas", "sub": "Parte específica. Ley 31/1995 (arts. 14 a 29) y manipulación de cargas. Incluye preguntas hechas con el temario del IVAP de Personal de Apoyo.", "preguntas": [{"id": "bkt08q01", "q": "¿Qué real decreto regula la manipulación manual de cargas que entraña riesgos, en particular dorsolumbares?", "o": ["Real Decreto 487/1997", "Real Decreto 486/1997", "Real Decreto 488/1997", "Real Decreto 39/1997"], "e": "El RD 487/1997 trata la manipulación manual de cargas. El 486 es lugares de trabajo; el 488, pantallas; el 39, servicios de prevención.", "r": "RD 487/1997"}, {"id": "bkt08q02", "q": "Según la guía técnica del INSST, en condiciones ideales el peso máximo recomendado para manipular una carga es:", "o": ["25 kg", "15 kg", "40 kg", "50 kg"], "e": "25 kg en general; 15 kg para mujeres, jóvenes o mayores; y según el temario del IVAP nunca más de 40 kg.", "r": "Guía técnica INSST, RD 487/1997"}, {"id": "bkt08q03", "q": "Si se quiere proteger a la mayoría de la población trabajadora (incluidas mujeres, jóvenes y personas mayores), el peso máximo recomendado es:", "o": ["15 kg", "25 kg", "10 kg", "30 kg"], "e": "La guía rebaja el límite a 15 kg para proteger a la mayoría de la población.", "r": "Guía técnica INSST"}, {"id": "bkt08q04", "q": "Según la guía del INSST, ¿a partir de qué peso una carga puede entrañar riesgo dorsolumbar?", "o": ["Más de 3 kg", "Más de 10 kg", "Más de 1 kg", "Más de 25 kg"], "e": "Las cargas de más de 3 kg pueden suponer riesgo dorsolumbar si se manipulan en malas condiciones.", "r": "Guía técnica INSST"}, {"id": "bkt08q05", "q": "Al levantar una caja pesada del suelo, la postura correcta es:", "o": ["Flexionar las piernas, mantener la espalda recta y la carga pegada al cuerpo", "Doblar la espalda con las piernas estiradas", "Levantarla con los brazos estirados", "Girar el tronco mientras se levanta"], "e": "Hay que hacer la fuerza con las piernas, no con la espalda, y mantener la carga cerca del cuerpo.", "r": "Guía técnica INSST"}, {"id": "bkt08q06", "q": "Si al transportar una carga hay que cambiar de dirección, lo correcto es:", "o": ["Girar moviendo los pies, sin torcer el tronco", "Girar el tronco manteniendo los pies quietos", "Girar rápido para acabar antes", "Soltar la carga y volver a cogerla"], "e": "Los giros de tronco con carga son una de las principales causas de lesión.", "r": "Guía técnica INSST"}, {"id": "bkt08q07", "q": "La zona más favorable para manipular una carga es:", "o": ["Cerca del cuerpo, entre la altura de los nudillos y la de los codos", "Por encima de los hombros", "A ras del suelo", "Con los brazos totalmente extendidos"], "e": "Cuanto más lejos del cuerpo y fuera de esa franja, mayor es el riesgo.", "r": "Guía técnica INSST"}, {"id": "bkt08q08", "q": "Ante una carga demasiado pesada o voluminosa, la persona conserje debe:", "o": ["Pedir ayuda o usar medios mecánicos (carretilla, transpalé)", "Moverla ella sola con cuidado", "Arrastrarla por el suelo tirando con la espalda", "Dejarla donde esté sin avisar"], "e": "La primera medida es evitar la manipulación manual o reducir el esfuerzo con ayudas mecánicas o entre varias personas.", "r": "RD 487/1997, art. 3"}, {"id": "bki31", "q": "Según el temario del IVAP, bajo ninguna circunstancia se manipularán cargas que excedan de:", "o": ["40 kg", "25 kg", "15 kg", "50 kg"], "e": "En general no se recomienda superar 25 kg; 15 kg para mujeres, jóvenes o mayores; nunca más de 40 kg.", "r": "Temario IVAP Personal de Apoyo (2021), tema 12"}, {"id": "bki32", "q": "Según el temario del IVAP, las cargas que pesan más de ___ constituyen un riesgo en sí mismas aunque no haya otras condiciones desfavorables:", "o": ["25 kilos", "3 kilos", "10 kilos", "40 kilos"], "e": "Más de 3 kg puede ser riesgo en condiciones desfavorables; más de 25 kg lo es por sí mismo.", "r": "Temario IVAP Personal de Apoyo (2021), tema 12"}, {"id": "bki33", "q": "¿Qué porcentaje de los accidentes laborales se atribuye a la manipulación manual de cargas según el temario del IVAP?", "o": ["Un 20-25 %", "Un 5 %", "Un 50 %", "Un 75 %"], "e": "Es una de las causas más frecuentes de accidentes laborales.", "r": "Temario IVAP Personal de Apoyo (2021), tema 12"}, {"id": "bki34", "q": "¿Qué norma regula las disposiciones mínimas de seguridad y salud en la manipulación manual de cargas?", "o": ["Real Decreto 487/1997", "Ley 10/1982", "Real Decreto 513/2017", "Ley 39/2015"], "e": "El RD 487/1997 obliga a evitar la manipulación o, si no se puede, a reducir el riesgo.", "r": "Temario IVAP Personal de Apoyo (2021), tema 12"}, {"id": "bki35", "q": "¿Cuál de estos es un factor de riesgo individual INTRÍNSECO en la manipulación de cargas?", "o": ["Sobrepeso o patología dorso-lumbar previa", "Suelo resbaladizo", "Ritmo impuesto por el proceso", "Iluminación inadecuada"], "e": "Intrínsecos: falta de aptitud física, patología previa y sobrepeso. Extrínsecos: falta de formación.", "r": "Temario IVAP Personal de Apoyo (2021), tema 12"}, {"id": "bki36", "q": "Para levantar sacos pesados, el temario del IVAP recomienda empezar:", "o": ["Colocándose con una rodilla en el suelo", "Inclinando la espalda con las piernas rectas", "Tirando del saco con un brazo", "Levantándolo por encima de la cabeza"], "e": "Después se sube el saco deslizándolo sobre la pierna, se apoya en la otra rodilla, se acerca al cuerpo y se levanta.", "r": "Temario IVAP Personal de Apoyo (2021), tema 12"}, {"id": "bki37", "q": "El sistema de levantamiento con tres puntos de apoyo se recomienda para:", "o": ["Tablones o materiales para recubrir paredes", "Sacos pesados", "Cajas pequeñas", "Personas"], "e": "Pasos: ponerse en cuclillas, inclinar el tablón y apoyar una esquina, y levantar.", "r": "Temario IVAP Personal de Apoyo (2021), tema 12"}, {"id": "bki38", "q": "Si hay que subir una carga desde el suelo hasta la altura de los hombros o más, el temario del IVAP indica:", "o": ["Apoyarla a medio camino para poder cambiar el agarre", "Hacerlo de un solo tirón", "Girar el tronco para ganar impulso", "Sujetarla con una sola mano"], "e": "También: depositar la carga y luego ajustarla, y espaciar los levantamientos.", "r": "Temario IVAP Personal de Apoyo (2021), tema 12"}, {"id": "bki39", "q": "Si la evaluación indica riesgo NO TOLERABLE en la manipulación de cargas, ¿cuál de estas medidas NO aparece en el temario del IVAP?", "o": ["Aumentar el ritmo de trabajo", "Utilizar ayudas mecánicas", "Reducir el tamaño de la carga", "Mejorar el entorno de trabajo"], "e": "Las medidas son ayudas mecánicas, organización del trabajo, reducir la carga y mejorar el entorno.", "r": "Temario IVAP Personal de Apoyo (2021), tema 12"}], "incluye": ["ehu-administrativa/b09:35+37", "getxo-conserje/ex27:19-24", "getxo-conserje/ex27c:51-57", "getxo-kirolak-auxiliar/t06:1-22", "getxo-conserje/t10:10-11"]}, {"id": "t09", "sig": "Tema 9", "titulo": "Tema 9. Trabajos auxiliares de oficina: fotocopiado, escáner, encuadernación, destructoras, etiquetado, plastificado, guillotinado, grapado y taladro", "sub": "Parte específica. Incluye preguntas del examen de Getxo del tema 21 del temario IVAP. Incluye preguntas hechas con el temario del IVAP de Personal de Apoyo.", "preguntas": [{"id": "bkt09q03", "q": "La encuadernación térmica consiste en:", "o": ["Unir las hojas con una tapa que lleva cola en el lomo y que se funde con calor", "Perforar las hojas y pasar una espiral", "Grapar las hojas por el lomo", "Plastificar las hojas una a una"], "e": "La tapa térmica tiene un adhesivo en el lomo que se activa con calor.", "r": ""}, {"id": "bki41", "q": "Si una fotocopiadora se atasca, según el temario del IVAP hay que:", "o": ["Dejar el interruptor encendido y sacar el papel suavemente, con cuidado con el rodillo fusor", "Apagarla y tirar fuerte del papel", "Abrir el tambor y limpiarlo con agua", "Seguir copiando hasta que salga solo"], "e": "El rodillo fusor alcanza alta temperatura.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki42", "q": "Si las copias salen claras, ¿qué puede ocurrir según el temario del IVAP?", "o": ["Falta tóner o el control de claridad está en una posición demasiado clara", "El papel es demasiado grueso", "La bandeja está mal colocada", "El original está al revés"], "e": "Si tras regularlo sigue igual, se avisa al servicio técnico.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki43", "q": "Si la fotocopiadora no se va a usar durante mucho tiempo, hay que:", "o": ["Desenchufarla, porque aunque esté en OFF puede funcionar un calentador contra la condensación", "Dejarla en OFF sin desenchufar", "Quitarle el tóner", "Dejarla encendida para que no se enfríe"], "e": "La revisión y limpieza por el servicio técnico es mensual.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki44", "q": "Según el temario del IVAP, para ver una imagen escaneada en pantalla es inútil una resolución mayor de:", "o": ["72 ppp", "300 ppp", "600 ppp", "1.200 ppp"], "e": "Para impresión de calidad hay que subir a 300 ppp o más.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki45", "q": "¿Qué formato de imagen es el que más comprime, aunque pierde algo de calidad?", "o": ["JPG", "TIF", "BMP", "GIF"], "e": "TIF es el de mejor calidad pero ocupa mucho; BMP es el más estándar y también ocupa mucho.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki46", "q": "Las termoencuadernadoras funcionan:", "o": ["Fundiendo con calor una sustancia plástica en un borde de las hojas que queda adherida", "Taladrando y pasando una espiral", "Grapando por el lomo", "Cosiendo las hojas"], "e": "Las otras encuadernadoras taladran el papel e insertan canutillos o espirales.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki47", "q": "Según el temario del IVAP, una destructora de oficina convierte el papel en tiras de aproximadamente:", "o": ["1 milímetro de anchura", "1 centímetro", "5 milímetros", "1 metro"], "e": "Las de oficina destruyen entre 5 y 20 hojas a la vez; las industriales, entre 70 y 500.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki48", "q": "¿Qué debe vigilar el personal que usa la destructora?", "o": ["El vaciado de la bolsa para que no se llene en exceso", "La temperatura del rodillo", "El nivel de tóner", "La resolución"], "e": "Una bolsa llena dificulta la entrada de más papel.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki49", "q": "¿Cómo funciona una plastificadora según el temario del IVAP?", "o": ["Dos rodillos a alta temperatura funden la cola de la funda, que queda pegada por ambas caras", "Una cuchilla corta el plástico a medida", "Se pega el plástico con cola en frío", "Se pulveriza un barniz"], "e": "El documento adquiere una consistencia plástica muy difícil de deteriorar.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki50", "q": "Las guillotinas manuales disponen de dos guías-regla para:", "o": ["Que los cortes tengan la medida y orientación adecuadas", "Sujetar la cuchilla", "Medir el grosor del papel", "Evitar que el papel se moje"], "e": "Una horizontal y otra vertical.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki51", "q": "Según el temario del IVAP, el etiquetado es:", "o": ["Colocar etiquetas o marbetes a objetos, cartas o materiales para su envío, archivo o clasificación", "Escribir el destinatario en un sobre", "Grapar documentos", "Numerar las páginas"], "e": "Es una de las tareas auxiliares de oficina del tema.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}, {"id": "bki52", "q": "Una impresora multifunción reúne, como mínimo, las funciones de:", "o": ["Impresora, escáner y fotocopiadora", "Impresora y destructora", "Fax y teléfono", "Escáner y plastificadora"], "e": "Según el modelo puede tener además fax, lector de tarjetas o disco duro.", "r": "Temario IVAP Personal de Apoyo (2021), tema 22"}], "incluye": ["getxo-conserje/t09:11-25", "getxo-conserje/ex27:85-88+90-92", "getxo-conserje/ex27c:84-87+90-91+94"]}, {"id": "t10", "sig": "Tema 10", "titulo": "Tema 10. Nociones básicas de cerrajería, fontanería, saneamiento, electricidad, carpintería, albañilería, calefacción y aire acondicionado. Herramientas y útiles de mantenimiento", "sub": "Parte específica. Incluye preguntas del examen de Getxo del tema 28 del temario IVAP. Incluye preguntas hechas con el temario del IVAP de Personal de Apoyo.", "preguntas": [{"id": "bki61", "q": "¿Qué es una cerradura de embutir?", "o": ["La alojada en una mortaja practicada en el canto de la puerta", "La fijada al tablero de la puerta sin empotrar", "La que no tiene llave y se acciona con un botón en el pomo", "La que se abre con una barra en puertas de emergencia"], "e": "La fijada al tablero es la cerradura de caja; la de pomos es tubular; la de barra es antipánico.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki62", "q": "La guarda de una cerradura es:", "o": ["La obstrucción metálica que impide introducir una llave que no corresponde", "La ranura para meter la llave", "La placa que se pone en el marco", "El muelle del pestillo"], "e": "La ranura de la llave es la bocallave.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki63", "q": "¿Con qué frecuencia basta engrasar las bisagras con aceite suave, según el temario del IVAP?", "o": ["1 o 2 veces al año", "Cada semana", "Cada mes", "Cada 5 años"], "e": "Si la puerta roza el suelo se pueden poner arandelas gruesas entre las bisagras.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki64", "q": "¿Qué herramienta sirve para inmovilizar piezas mientras se trabaja sobre ellas?", "o": ["El sargento", "La escofina", "La lima", "El formón"], "e": "El formón es de corte de precisión; la escofina desbasta; la lima lija y afila.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki65", "q": "¿Qué diferencia hay entre la llave de paso y la llave de registro?", "o": ["La de paso está en el tubo de alimentación; la de registro, al final de la acometida", "Son lo mismo", "La de registro está en cada grifo", "La de paso solo existe en calefacción"], "e": "Ambas permiten cortar el agua, en distintos puntos de la instalación.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki66", "q": "El purgado de una instalación consiste en:", "o": ["Eliminar el aire de las tuberías", "Vaciar el agua de la cisterna", "Cambiar las juntas", "Limpiar los sifones"], "e": "Concepto de fontanería del tema 28.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki67", "q": "¿Qué hace una válvula de seguridad?", "o": ["Se abre sola cuando la presión supera el valor de tarado y descarga el exceso", "Impide que el agua circule en sentido contrario", "Mide el consumo", "Corta el agua a todo el edificio"], "e": "La que impide el paso en sentido contrario es la válvula de retención.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki68", "q": "Ante un escape o rotura de tubería, lo primero según el temario del IVAP es:", "o": ["Aislar el ramal cerrando la válvula de corte más próxima", "Llamar al seguro", "Poner un cubo y esperar", "Cortar la luz"], "e": "Después se repara de forma provisional con abrazaderas o cintas de goma.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki69", "q": "Para descongelar una tubería, el temario del IVAP indica:", "o": ["Aportar calor externo, por ejemplo con trapos calientes", "Golpearla con un martillo", "Echar sal dentro", "Cortar la tubería"], "e": "Para prevenirlo se mantiene un pequeño flujo de agua.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki70", "q": "Las bajantes son canalizaciones que conducen el agua:", "o": ["Verticalmente hasta la arqueta a pie de bajante o el colector", "Horizontalmente hasta el alcantarillado", "Desde la red pública al edificio", "Desde el depósito a los grifos"], "e": "El colector lleva el agua desde las bajantes hasta el alcantarillado público.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki71", "q": "Un sistema separativo de saneamiento es aquel en el que:", "o": ["Las aguas residuales y las pluviales van por conducciones independientes", "Todas las aguas van juntas", "Se separan los residuos sólidos", "Cada piso tiene su propia bajante"], "e": "Definición del temario del IVAP.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki72", "q": "¿Cada cuánto tiempo aproximadamente se limpian los sifones según el temario del IVAP?", "o": ["Cada 6 meses", "Cada semana", "Cada 5 años", "Nunca"], "e": "Los sifones filtran residuos sólidos y evitan malos olores.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki73", "q": "¿Qué frecuencia tiene la red eléctrica?", "o": ["50 Hz", "60 Hz", "230 Hz", "400 Hz"], "e": "La tensión usual es 230 V entre fase y neutro y 400 V entre fases.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki74", "q": "Según el Reglamento Electrotécnico de Baja Tensión, las instalaciones eléctricas deben realizarlas:", "o": ["Únicamente personas instaladoras autorizadas", "Cualquier conserje con experiencia", "El personal de limpieza", "La empresa de la fotocopiadora"], "e": "Lo cita el temario del IVAP en las tareas de electricidad.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki75", "q": "¿Qué característica tienen los destornilladores de electricista?", "o": ["El vástago está cubierto por una funda aislante y el mango es de plástico aislante", "Son siempre de estrella", "Tienen la punta imantada", "Son más largos que los normales"], "e": "Así protegen del riesgo eléctrico.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki76", "q": "¿Qué herramienta de seguridad permite determinar qué partes de la instalación tienen tensión?", "o": ["El comprobador de tensión", "Las pinzas de punta", "La borna de empalme", "El cortatubos"], "e": "Las pinzas eléctricas miden intensidad y tensión en un circuito.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki77", "q": "Un tablero contrachapado está formado por:", "o": ["Láminas de madera con las vetas cruzadas perpendicularmente", "Partículas de madera unidas con resinas", "Virutas muy finas prensadas (DM)", "Madera maciza"], "e": "El aglomerado es de partículas con resinas; el DM es un aglomerado de virutas más pequeñas.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki78", "q": "El mortero de cemento se hace con:", "o": ["Cemento, agua y arena", "Yeso, agua y arena", "Cal y agua", "Cemento y pintura"], "e": "La mezcla de yeso, agua y arena es el enyesado.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki79", "q": "Las humedades junto a ventanas y puertas suelen deberse, según el temario del IVAP, a:", "o": ["Condensación", "Roturas de tubería", "Filtraciones del tejado", "Mala pintura"], "e": "Se reparan una vez seca la zona con masa selladora.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}, {"id": "bki80", "q": "Los equipos de iluminación de emergencia de los locales públicos:", "o": ["Tienen baterías que dan una iluminación mínima para evacuar si falla el suministro", "Solo se encienden en los simulacros", "Funcionan con gasóleo", "Son opcionales"], "e": "Disponen de piloto de señalización y se colocan en recorridos de evacuación.", "r": "Temario IVAP Personal de Apoyo (2021), tema 28"}], "incluye": ["getxo-conserje/t10:18-32", "getxo-conserje/ex27:52-63+107-109", "getxo-conserje/ex27c:99-100+107-109"]}, {"id": "t11", "sig": "Tema 11", "titulo": "Tema 11. Administración educativa no universitaria: principios generales. Organización de los centros docentes. Centros públicos de Educación Infantil y Primaria de Barakaldo (directorio)", "sub": "Parte específica. Temario IVAP (tema 15) y directorio de centros del Ayuntamiento de Barakaldo.", "preguntas": [{"id": "bkt11q07", "q": "¿Qué ley regula actualmente la educación del País Vasco y sustituye a la Ley de la Escuela Pública Vasca?", "o": ["Ley 17/2023, de Educación del País Vasco", "Ley 1/1993", "Ley 10/1982", "Ley 2/2016"], "e": "La Ley 17/2023 sustituyó a la Ley 1/1993 de la Escuela Pública Vasca.", "r": "Ley 17/2023"}, {"id": "bkt11q08", "q": "En Barakaldo, la conservación, el mantenimiento y la vigilancia de los edificios de los CEIP públicos corresponden a:", "o": ["El Ayuntamiento de Barakaldo", "El Gobierno Vasco", "La Diputación Foral de Bizkaia", "La AMPA de cada centro"], "e": "La LBRL atribuye al municipio la conservación, el mantenimiento y la vigilancia de los centros públicos de infantil, primaria y educación especial. Por eso el conserje escolar es personal municipal.", "r": "Ley 7/1985, art. 25.2.n"}, {"id": "bkd01", "q": "¿Cuántos centros públicos de Educación Infantil y Primaria (CEP) aparecen en el directorio del Ayuntamiento de Barakaldo?", "o": ["12", "8", "4", "20"], "e": "Alkartu Ikastola, Arteagabeitia, Gurutzeta, Ibaibe, Juan Ramón Jiménez, Larrea, Mukusuluba, Munoa, N. S. El Pilar, Rontegi, S. T. Bagaza y Zuazo.", "r": "Directorio de centros de educación, Ayuntamiento de Barakaldo (barakaldo.eus)"}, {"id": "bkd02", "q": "¿Cuál de estos es un centro público de Infantil y Primaria de Barakaldo?", "o": ["CEP Munoa LHI", "Co. San Juan Bosco Ik", "Co. Alazne Ik", "Co. La Inmaculada Ik"], "e": "Los «Co. … Ik» del directorio son centros concertados.", "r": "Directorio de centros de educación, Ayuntamiento de Barakaldo (barakaldo.eus)"}, {"id": "bkd03", "q": "¿Cuál de estos centros de Barakaldo es CONCERTADO y no público?", "o": ["Co. Ntra. Sra. del Rosario Ik", "CEP Gurutzeta LHI", "CEP Larrea LHI", "CEP Zuazo LHI"], "e": "En el directorio, Ntra. Sra. del Rosario figura entre los concertados.", "r": "Directorio de centros de educación, Ayuntamiento de Barakaldo (barakaldo.eus)"}, {"id": "bkd04", "q": "Ojo con los nombres: ¿cuál de estos centros es PÚBLICO?", "o": ["CEP N. S. El Pilar LHI", "Co. Ntra. Sra. de Begoña Ik", "Co. El Regato Ik", "Co. San Paulino de Nola Ik"], "e": "El Pilar es un CEP público; Begoña, El Regato y San Paulino de Nola son concertados.", "r": "Directorio de centros de educación, Ayuntamiento de Barakaldo (barakaldo.eus)"}, {"id": "bkd05", "q": "¿Qué centro público de Infantil y Primaria de Barakaldo es una ikastola?", "o": ["CEP Alkartu Ikastola LHI", "CEP Rontegi LHI", "CEP Ibaibe LHI", "CEP Mukusuluba LHI"], "e": "Así aparece en el directorio municipal.", "r": "Directorio de centros de educación, Ayuntamiento de Barakaldo (barakaldo.eus)"}, {"id": "bkd06", "q": "¿Cuál de estos es un instituto público de Secundaria de Barakaldo?", "o": ["IES Minas BHI", "CEP S. T. Bagaza LHI", "Co. Alazne Ik", "Inguralde"], "e": "Los IES públicos son Antonio Trueba, Beurko, Cruces y Minas.", "r": "Directorio de centros de educación, Ayuntamiento de Barakaldo (barakaldo.eus)"}, {"id": "bkd07", "q": "¿Cuál de estas es una de las tres escuelas infantiles municipales de Barakaldo?", "o": ["Escuela Infantil Municipal Urban", "CEP Juan Ramón Jiménez LHI", "IES Cruces", "Co. San Vicente de Paúl Ik"], "e": "Las escuelas infantiles municipales son Arteagabeitia, Llano y Urban.", "r": "Directorio de centros de educación, Ayuntamiento de Barakaldo (barakaldo.eus)"}, {"id": "bkd08", "q": "¿Qué centro de Barakaldo aparece en el directorio como centro de formación profesional?", "o": ["IEFPS N. Larburu GLHBI", "CEP Zuazo LHI", "IES Beurko BHI", "C.E.P.A."], "e": "En FP figuran el CPPCPI (CIP) y el IEFPS N. Larburu.", "r": "Directorio de centros de educación, Ayuntamiento de Barakaldo (barakaldo.eus)"}, {"id": "bkd09", "q": "¿Cuál de estos centros NO es un CEP público de Barakaldo?", "o": ["Co. El Regato Ik", "CEP Ibaibe LHI", "CEP Arteagabeitia LHI", "CEP Juan Ramón Jiménez LHI"], "e": "El Regato aparece entre los concertados.", "r": "Directorio de centros de educación, Ayuntamiento de Barakaldo (barakaldo.eus)"}, {"id": "bki91", "q": "Según el temario del IVAP, la competencia en materia de educación es:", "o": ["Compartida: el Estado aprueba la normativa básica y la Comunidad Autónoma la desarrolla y ejecuta", "Exclusiva del Estado", "Exclusiva de los ayuntamientos", "Exclusiva de las diputaciones forales"], "e": "El Gobierno Vasco es el titular de los centros públicos.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki92", "q": "¿Qué corresponde a los municipios en educación según el temario del IVAP?", "o": ["Cooperar en la creación, construcción y mantenimiento de los centros públicos y velar por la escolaridad obligatoria", "Nombrar al profesorado", "Aprobar el currículo", "Seleccionar a la dirección de los centros"], "e": "Además participan en el gobierno de los centros a través de su representante en el consejo escolar.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki93", "q": "Las «circunscripciones escolares» son:", "o": ["Unidades básicas de distribución territorial para organizar y planificar los servicios docentes", "Los barrios de cada municipio", "Los consejos escolares", "Las aulas de cada centro"], "e": "El Gobierno Vasco las crea por decreto y definen el mapa escolar.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki94", "q": "En caso de falta de plazas en un centro, ¿qué criterios de admisión cita el temario del IVAP?", "o": ["Renta familiar, proximidad del domicilio y hermanos en el centro", "Orden de llegada", "Nota del alumnado", "Sorteo únicamente"], "e": "El derecho de libre elección de centro puede limitarse por la oferta.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki95", "q": "¿Qué tres autonomías reconoce a los centros la Ley de la Escuela Pública Vasca?", "o": ["De organización, pedagógica y de gestión", "Financiera, política y judicial", "Lingüística, religiosa y deportiva", "Ninguna"], "e": "Instrumentos: proyecto educativo, proyecto curricular, proyecto de gestión y reglamento de organización y funcionamiento.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki96", "q": "¿Quién aprueba el reglamento de organización y funcionamiento de un centro público?", "o": ["El Órgano Máximo de Representación (consejo escolar)", "El claustro", "La dirección", "El Ayuntamiento"], "e": "Después el centro lo remite a la Administración educativa.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki97", "q": "En el modelo lingüístico D, el currículo se imparte:", "o": ["En euskera", "Básicamente en castellano", "En euskera y castellano", "En inglés"], "e": "Modelo A: básicamente en castellano; B: en euskera y castellano; D: en euskera.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki98", "q": "¿Quién preside el Órgano Máximo de Representación de un centro público?", "o": ["El director o la directora", "El concejal del Ayuntamiento", "El representante de las familias", "El secretario o la secretaria"], "e": "El secretario o secretaria actúa como secretario del órgano con voz y sin voto.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki99", "q": "¿Forma parte del Órgano Máximo de Representación un representante del personal de administración y servicios?", "o": ["Sí, uno", "No", "Sí, tres", "Solo en secundaria"], "e": "También forman parte un concejal o representante del Ayuntamiento, profesorado, familias y alumnado (desde 1.º de ESO).", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki100", "q": "¿Por cuánto tiempo se nombra al director o directora de un centro público?", "o": ["Cuatro años, renovables", "Dos años", "Seis años", "Indefinidamente"], "e": "Se selecciona por concurso de méritos entre profesorado funcionario de carrera.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki101", "q": "¿Cuál de estos es un órgano UNIPERSONAL del centro?", "o": ["El jefe o la jefa de estudios", "El claustro", "La asamblea de padres y madres", "El equipo directivo"], "e": "Unipersonales: dirección, jefatura de estudios, secretaría y, en su caso, administración.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}, {"id": "bki102", "q": "¿Quién ejerce la jefatura de todo el personal adscrito al centro, incluido el no docente?", "o": ["El director o la directora", "El jefe de estudios", "El Ayuntamiento", "El consejo escolar"], "e": "Es una de las funciones de dirección del personal.", "r": "Temario IVAP Personal de Apoyo (2021), tema 15"}], "incluye": ["getxo-conserje/t07e:1-3+5-8+15-25", "getxo-conserje/ex27:38-48"]}, {"id": "sp", "sig": "2.º ejercicio", "titulo": "2.º ejercicio. Supuestos prácticos tipo test de Conserje Escolar", "sub": "Situaciones del día a día en un colegio. El examen real tiene 30 preguntas + 10 de reserva en 60 minutos. Respuestas orientativas: no hay solucionario oficial.", "preguntas": [{"id": "bksp01", "q": "Son las 9:15 y una niña de 2.º de primaria se cae en el patio y sangra por la rodilla. Eres la persona conserje y estás cerca. ¿Qué haces primero?", "o": ["Atenderla con el botiquín usando guantes y avisar a su tutor/a o a la dirección", "Llamar directamente a la familia para que venga a buscarla", "Darle un analgésico del botiquín", "Mandarla sola a clase para que la vea su profesora"], "e": "Primeros auxilios básicos con guantes y aviso al centro. La persona conserje no da medicamentos ni decide llamar a la familia sin la dirección.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp02", "q": "A la salida, una persona que no conoces dice que viene a recoger a un niño de infantil «de parte de la madre». No figura en la lista de autorizados. ¿Qué haces?", "o": ["No entregar al niño y avisar a la tutora o a la dirección, que comprobarán con la familia", "Entregarlo si la persona sabe el nombre del niño", "Entregarlo si el niño la reconoce", "Llamar a la Policía inmediatamente"], "e": "Solo se entrega a personas autorizadas. Cualquier duda la resuelve la dirección contactando con la familia.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp03", "q": "Al abrir el colegio por la mañana, salta la alarma de intrusión y ves una ventana rota. ¿Qué es lo correcto?", "o": ["No entrar, avisar a la Policía Municipal y a la central de alarmas, y después a la dirección y al Ayuntamiento", "Entrar a revisar qué falta", "Desconectar la alarma y abrir el centro con normalidad", "Recoger los cristales para que no se corte nadie y seguir"], "e": "Ante un posible robo no se entra ni se tocan las pruebas: primero aviso a la Policía.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp04", "q": "Durante las clases ves salir agua por debajo de la puerta de los baños de la planta baja. ¿Qué haces primero?", "o": ["Cerrar la llave de paso de esa zona y señalizar el suelo mojado", "Llamar a un fontanero particular", "Fregar el agua y esperar a ver si para", "Dejarlo para el final de la jornada"], "e": "Primero cortar el agua y evitar caídas. Después se comunica la avería por el cauce establecido (Ayuntamiento).", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp05", "q": "Suena la alarma de incendios del colegio. ¿Cuál es una tarea típica de la persona conserje según el plan de autoprotección?", "o": ["Abrir las puertas exteriores, cortar los suministros si se le ha asignado y recibir a los servicios de emergencia", "Recoger los papeles de secretaría", "Volver a por el alumnado que se ha quedado en el aula sin avisar a nadie", "Usar el ascensor para bajar más rápido"], "e": "En el plan de autoprotección, la conserjería suele encargarse de abrir salidas, cortar suministros y orientar a bomberos. Nunca se usa el ascensor.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp06", "q": "Encuentras en el patio una jeringuilla usada. ¿Cómo actúas?", "o": ["Apartar al alumnado, cogerla con guantes y pinzas y depositarla en un recipiente rígido, y avisar a la dirección", "Cogerla con la mano y tirarla a la papelera", "Taparla con tierra", "Dejarla y avisar al día siguiente"], "e": "Hay riesgo biológico: nunca con la mano, en recipiente rígido y aviso.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp07", "q": "Una persona usuaria se queda atrapada en el ascensor del centro. ¿Qué haces?", "o": ["Tranquilizarla, pulsar o activar el aviso a la empresa mantenedora y no intentar sacarla tú si no tienes formación", "Abrir las puertas a la fuerza", "Dar golpes en la cabina para que se mueva", "Cortar la luz del edificio"], "e": "El rescate lo hace la empresa mantenedora o los bomberos. La conserjería calma y avisa.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp08", "q": "La AMPA te pide las llaves del gimnasio para una actividad un sábado. ¿Qué haces?", "o": ["Comprobar que el uso está autorizado por el Ayuntamiento o la dirección según el procedimiento, y registrar la entrega y devolución de llaves", "Dárselas porque son de la AMPA del centro", "Negarte siempre", "Hacer una copia de la llave para dejársela"], "e": "El uso fuera del horario escolar necesita autorización. Las llaves se entregan con registro.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp09", "q": "Salta el diferencial del cuadro eléctrico y se queda sin luz un pasillo. ¿Qué es lo correcto?", "o": ["Intentar rearmarlo una vez y, si vuelve a saltar, dejarlo desconectado y avisar de la avería", "Puentear el diferencial para que no salte", "Subir y bajar el diferencial muchas veces seguidas", "Abrir el cuadro y revisar los cables"], "e": "Si salta de nuevo hay un defecto. Puentear o manipular el cuadro es peligroso y no es tarea del conserje.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp10", "q": "Ves que una puerta cortafuegos del pasillo está sujeta con una cuña para que quede abierta. ¿Qué haces?", "o": ["Quitar la cuña para que la puerta pueda cerrarse sola y explicar el motivo a quien la puso", "Dejarla así porque ventila", "Atarla con una cuerda para que no se mueva", "Quitarle el muelle de cierre"], "e": "Las puertas cortafuegos deben poder cerrarse solas en caso de incendio.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp11", "q": "Llega un paquete a nombre de una profesora con la indicación «personal». ¿Qué haces?", "o": ["Registrarlo y entregárselo a ella sin abrirlo", "Abrirlo para comprobar el contenido", "Dárselo a la dirección para que lo abra", "Devolverlo al mensajero"], "e": "La correspondencia personal no se abre. Se registra y se entrega a la destinataria.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp12", "q": "Un profesor te pide 200 copias de un examen a doble cara, grapadas, para dentro de 10 minutos, y la fotocopiadora tiene poco papel. ¿Qué haces primero?", "o": ["Cargar papel, configurar doble cara, clasificar y grapar, y hacer una copia de prueba", "Hacer las 200 copias directamente", "Decirle que no da tiempo", "Hacerlas a una cara para ir más rápido"], "e": "La copia de prueba evita estropear 200 copias. Hay que preparar la máquina antes de empezar.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp13", "q": "En una tormenta se rompe una rama grande que cae junto a la entrada del patio. ¿Qué haces?", "o": ["Señalizar o acotar la zona, impedir el paso y avisar al Ayuntamiento (servicio de parques o mantenimiento)", "Cortar la rama tú con una sierra", "Dejar que el alumnado la aparte", "No hacer nada porque ya ha caído"], "e": "Primero seguridad (acotar) y después comunicar al servicio responsable.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp14", "q": "Necesitas cambiar un fluorescente del techo de un aula. ¿Qué es lo correcto?", "o": ["Cortar la corriente, usar una escalera de tijera en buen estado con los dos tramos abiertos y no subir al último peldaño", "Subirse a una silla con ruedas", "Cambiarlo con la luz encendida para ver mejor", "Usar una escalera con un peldaño roto si tienes cuidado"], "e": "Corriente cortada y escalera adecuada. Nunca sillas ni último peldaño.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp15", "q": "Una madre llega muy enfadada porque no le han dejado pasar al aula de su hijo. ¿Cómo actúas?", "o": ["Escucharla con calma, no discutir, explicarle la norma del centro y avisar a la dirección para que la atienda", "Dejarla pasar para que se calme", "Responderle en el mismo tono", "Pedirle que se vaya sin escucharla"], "e": "Escucha activa, calma y derivar a quien tiene la competencia.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp16", "q": "Al final de la jornada, ¿cuál es una tarea habitual de cierre de la persona conserje?", "o": ["Revisar que no quede nadie, cerrar puertas y ventanas, apagar luces y conectar la alarma", "Dejar las ventanas abiertas para ventilar toda la noche", "Dejar la puerta principal abierta para el personal de limpieza sin avisar", "Desconectar la alarma para que no salte"], "e": "El cierre incluye comprobar el edificio, cerrar, apagar y activar la alarma.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp17", "q": "Un alumno ha perdido una chaqueta y otro la ha encontrado. ¿Qué haces con los objetos perdidos?", "o": ["Guardarlos en el lugar establecido para objetos perdidos y anotarlos si hay registro", "Dárselos al primer alumno que diga que es suyo", "Tirarlos a la semana", "Llevártelos a casa para lavarlos"], "e": "Se custodian en el punto de objetos perdidos según la norma del centro.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp18", "q": "Un producto de limpieza se ha derramado en el almacén y huele muy fuerte. ¿Qué haces?", "o": ["Ventilar, salir de la zona, consultar la etiqueta o la ficha de seguridad y avisar", "Mezclarlo con lejía para neutralizarlo", "Recogerlo sin guantes con un trapo", "Cerrar la puerta y seguir trabajando dentro"], "e": "Nunca mezclar productos. Ventilar y seguir la ficha de datos de seguridad.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp19", "q": "Ves a una persona adulta desconocida dentro del recinto escolar en horario de clase. ¿Qué haces?", "o": ["Acercarte con educación, preguntarle a quién busca y acompañarla a la conserjería o a la dirección", "Ignorarla", "Gritarle que se vaya", "Dejarla pasear por el centro"], "e": "El control de accesos implica identificar y acompañar a las visitas.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp20", "q": "Mientras estás atendiendo el teléfono, llega una persona al mostrador. ¿Qué haces?", "o": ["Indicarle con un gesto que enseguida la atiendes y terminar la llamada lo antes posible", "Ignorarla hasta acabar", "Colgar el teléfono sin despedirte", "Decirle que vuelva otro día"], "e": "Hay que reconocer a la persona presente y atenderla en cuanto se pueda.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp21", "q": "Por la mañana la calefacción no funciona y hace mucho frío en las aulas. ¿Qué haces?", "o": ["Comprobar lo básico que te corresponde (que haya corriente, el termostato y si la caldera da algún aviso) y comunicar la avería al Ayuntamiento y a la dirección", "Abrir la caldera y manipularla", "Traer estufas de gas de tu casa", "No hacer nada hasta que se quejen"], "e": "La conserjería hace comprobaciones básicas y avisa. Las calderas solo las tocan técnicos autorizados.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp22", "q": "En el patio hay un perro suelto sin dueño durante el recreo. ¿Qué haces?", "o": ["Alejar al alumnado, no acercarte bruscamente, cerrar accesos si se puede y avisar a la Policía Municipal", "Echarlo a patadas", "Dejar que los niños jueguen con él", "Darle comida para que se quede"], "e": "Seguridad del alumnado y aviso al servicio municipal correspondiente.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp23", "q": "Te piden preparar el salón de actos para una reunión de familias con proyección. ¿Qué es lo primero que compruebas?", "o": ["Que el proyector, el ordenador, el sonido y el micrófono funcionan antes de que llegue la gente", "Solo que haya sillas", "Que la puerta de emergencia esté cerrada con llave", "Nada: lo prepara quien da la charla"], "e": "Probar los medios audiovisuales antes evita problemas durante la reunión.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp24", "q": "Ves pintadas nuevas en la fachada del colegio. ¿Qué haces?", "o": ["Hacer fotos, anotar la fecha y comunicarlo al Ayuntamiento y a la dirección", "Pintar encima con la pintura que tengas", "Borrarlas con disolvente sin protección", "No avisar porque no es grave"], "e": "Se documenta y se comunica para que se gestione la limpieza o reparación.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp25", "q": "¿Dónde deben estar las vías de evacuación y las salidas de emergencia del colegio?", "o": ["Libres de obstáculos y señalizadas en todo momento", "Cerradas con llave durante las clases", "Libres solo en los simulacros", "Ocupadas con mobiliario si no hay sitio en el almacén"], "e": "Las salidas de emergencia deben estar siempre despejadas y señalizadas.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp26", "q": "Revisas el botiquín y ves que faltan gasas y hay un producto caducado. ¿Qué haces?", "o": ["Retirar lo caducado y comunicar lo que falta para reponerlo", "Dejarlo así hasta fin de curso", "Usar el producto caducado si está cerrado", "Comprar medicamentos para completarlo"], "e": "El botiquín debe estar completo y sin caducados. La reposición se pide por el cauce del centro.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp27", "q": "Una alumna de 1.º se pone a llorar en la entrada porque no quiere entrar al colegio. ¿Qué haces?", "o": ["Tranquilizarla con calma y avisar a su tutora o a la persona responsable para que la acompañe", "Obligarla a entrar sola", "Llamar a la Policía", "Dejar que se vaya a casa"], "e": "La persona conserje apoya y avisa al profesorado responsable.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp28", "q": "Encuentras una cerradura de un aula que cuesta mucho abrir. ¿Qué puedes hacer primero?", "o": ["Aplicar un lubricante adecuado para cerraduras (grafito o específico) y, si sigue igual, comunicar la avería", "Echarle aceite de cocina", "Forzarla con un destornillador", "Dejar el aula sin cerrar"], "e": "El mantenimiento básico de cerraduras se hace con lubricante específico; si no se arregla, se comunica.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp29", "q": "Antes de un simulacro de evacuación, ¿qué debe saber la persona conserje?", "o": ["Las tareas que le asigna el plan de autoprotección del centro", "Nada, porque solo participa el profesorado", "Solo dónde está la salida principal", "Que debe recoger su mochila antes de salir"], "e": "Cada persona tiene un papel en el plan de autoprotección; la conserjería suele abrir salidas y controlar accesos.", "r": "Supuesto práctico (2.º ejercicio)"}, {"id": "bksp30", "q": "Llega una visita que pide hablar con la directora, que está en una reunión. ¿Qué haces?", "o": ["Preguntar su nombre y el motivo, ofrecerle esperar o dejar recado, y avisar a la directora cuando pueda atenderla", "Interrumpir la reunión", "Decirle que la directora no está para no molestar", "Dejarle pasar a la reunión"], "e": "Atención correcta: identificar, informar y dar opciones sin interrumpir sin motivo.", "r": "Supuesto práctico (2.º ejercicio)"}]}]});
